// Runtime access to the trimmed CC-CEDICT asset generated by
// scripts/build-dictionary.mjs. The asset is lazy-loaded over fetch and
// never joins the initial JS bundle; a failed load resolves to null and
// the reader silently keeps wordless tokens.

export interface DictRecord {
  /** Tone-marked pinyin, syllables space-separated. */
  pinyin: string;
  /** Up to three leading glosses, "; "-separated. */
  def: string;
}

/** Anything that can supply readings for an unaligned word span. */
export interface ReadingProvider {
  lookup(text: string): DictRecord[] | undefined;
}

export type DictStatus = 'idle' | 'loading' | 'ready' | 'unavailable';

interface DictFile {
  meta: { release: string; entries: number };
  entries: Record<string, [string, string][]>;
  aliases: Record<string, string>;
}

export interface DictIndex extends ReadingProvider {
  readonly release: string;
  readonly headwords: number;
}

let pending: Promise<DictIndex | null> | null = null;

/** Fetch and index the dictionary once; safe to call from any component. */
export function loadDictionary(): Promise<DictIndex | null> {
  if (!pending) {
    pending = fetch(`${import.meta.env.BASE_URL}dict/cedict.json`)
      .then((res) => {
        if (!res.ok) throw new Error(`dictionary HTTP ${res.status}`);
        return res.json() as Promise<DictFile>;
      })
      .then(
        (file): DictIndex => ({
          release: file.meta.release,
          headwords: Object.keys(file.entries).length,
          lookup: (text: string): DictRecord[] | undefined => {
            const direct = file.entries[text];
            if (direct) {
              return direct.map(([pinyin, def]) => ({ pinyin, def }));
            }
            const simp = file.aliases[text];
            if (!simp) return undefined;
            return file.entries[simp]?.map(([pinyin, def]) => ({
              pinyin,
              def,
            }));
          },
        }),
      )
      .catch(() => null);
  }
  return pending;
}
